INSERT INTO public.atms (terminal_id, location_id, machine_type, brand, model, operation_hours, deployment_type, capacity_amount, low_threshold_amount, critical_threshold_amount, blacklisted, is_active)
SELECT s.terminal_id, l.id, s.machine_type, s.brand, s.model, s.operation_hours, s.deployment_type, s.capacity_amount, s.low_threshold_amount, s.critical_threshold_amount, s.blacklisted, s.is_active
FROM seed_atms s
JOIN public.locations l
  ON l.type = s.location_type
 AND l.name = s.location_name
 AND l.city_or_regency = s.city_or_regency
 AND l.province = s.province
ON CONFLICT (terminal_id) DO UPDATE
SET
    location_id = EXCLUDED.location_id,
    machine_type = EXCLUDED.machine_type,
    brand = EXCLUDED.brand,
    model = EXCLUDED.model,
    operation_hours = EXCLUDED.operation_hours,
    deployment_type = EXCLUDED.deployment_type,
    capacity_amount = EXCLUDED.capacity_amount,
    low_threshold_amount = EXCLUDED.low_threshold_amount,
    critical_threshold_amount = EXCLUDED.critical_threshold_amount,
    blacklisted = EXCLUDED.blacklisted,
    is_active = EXCLUDED.is_active,
    updated_at = now();

COMMIT;